// Run in the exact built source with Node24+, after selecting the original project archive from its retained ZIP.
import { readFile, mkdir, writeFile, rename, unlink } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createHash, randomUUID } from 'node:crypto';

const [sourceArg, archiveArg, outputArg] = process.argv.slice(2);
if (!sourceArg || !archiveArg || !outputArg) throw Error('Pass actual built-source root, original handover archive and private customer-output root.');
if (Number(process.versions.node.split('.')[0]) < 24) throw Error('Use the original Node24+ runtime.');
const source = resolve(sourceArg), archive = resolve(archiveArg), output = resolve(outputArg);
const digest = b => createHash('sha256').update(b).digest('hex');
const gitBlob = b => createHash('sha1').update('blob ' + b.length + '\0').update(b).digest('hex');
const need = (ok, message) => { if (!ok) throw Error(message); };
const load = p => import(pathToFileURL(join(source,p)).href);
const sourcePins = {
  "products/coingecko/delivery.mjs": "d6166fdf8c8a99e379cc3b8ffd5e2f30a4b4c6be",
  "products/coingecko/cli.mjs": "16f22997f6cd1cc23cfe26601347270ba05d3222",
  "stellar/scf-starforge-20261009/partners/coingecko-stellar-market/workspace/model.mjs": "34291e5c411a74e86cd332f72d0c3d56966da1d6",
  "stellar/scf-starforge-20261009/partners/coingecko-stellar-market/workspace/store.mjs": "78d526472d4028054de628ffbb59bf5cb23b833d",
  "stellar/scf-starforge-20261009/partners/coingecko-stellar-market/workspace/recovery.mjs": "e1eb36055f88317adaa4ac1a497552f17fc63764",
  "stellar/scf-starforge-20261009/partners/coingecko-stellar-market/workspace/server.mjs": "76e70af422d580c371889d4f7c33c27678ca378b",
  "stellar/scf-starforge-20261009/partners/coingecko-stellar-market/market.mjs": "70adca79882878a6c76a836ae1ed84dc4039a136"
};
for (const [p, sha] of Object.entries(sourcePins)) need(gitBlob(await readFile(join(source,p))) === sha, 'Built source differs: ' + p);
const product = await load('products/coingecko/delivery.mjs');
const modelModule = await load('stellar/scf-starforge-20261009/partners/coingecko-stellar-market/workspace/model.mjs');
const serverModule = await load('stellar/scf-starforge-20261009/partners/coingecko-stellar-market/workspace/server.mjs');
const recovery = await load('stellar/scf-starforge-20261009/partners/coingecko-stellar-market/workspace/recovery.mjs');
const originalBytes = await readFile(archive), original = recovery.readProjectArchive(originalBytes);
need(original.payload.project.id === '05c3eb83-9c7a-42a0-a683-4024e5f755b8', 'Select the original completed project, not another recovered copy.');
await mkdir(output,{recursive:true,mode:0o700});
const deliveryDirectory = join(output,'delivery'), state = join(output,'recipient-market');
const actor = 'Commons customer delivery receiver';
const operation = 'COINGECKO-PRODUCT-DELIVERY-5403-20261012';
const receivingInput = {directory:deliveryDirectory,state,actor,operation};
const resultPath = join(output,'customer-receiving.json');
const input = {operation,actor,sourceCommit:'ada4e3261a421010f93ef4bda9ce8b0b2624d4c1',sourcePins,
  archiveSha256:digest(originalBytes),archiveBytes:originalBytes.length,originalProjectId:original.payload.project.id,
  outputDirectory:output,deliveryDirectory,recipientStateDirectory:state};
let retained;
try { retained=JSON.parse(await readFile(resultPath,'utf8')); }
catch(error) { if(error.code!=='ENOENT')throw error; }
if(retained)need(retained.schema==='commons.coingecko-complete-customer-receiving.v1'&&
  JSON.stringify(retained.input)===JSON.stringify(input)&&Array.isArray(retained.stages)&&Array.isArray(retained.attempts),
  'Continue the original source, archive, customer directory and operation; preserve the existing result.');
function printResult(value,replayed=false) {
  process.stdout.write(JSON.stringify({status:value.status,operation,replayed,result:resultPath,
    completedAt:value.completedAt,deliveryDirectory,recipientStateDirectory:state,recipientProjectId:value.recipientProjectId,
    stages:value.stages.map(x=>({name:x.name,status:x.status}))})+'\n');
}
if(retained?.status==='RECEIVED') {
  // The product's original idempotent receiver verifies the archive, complete delivery,
  // retained database identity and every original source file without restoring over later work.
  const current=await product.receiveCoinGeckoDelivery(receivingInput);
  need(current.replayed===true&&current.recipientProjectId===retained.recipientProjectId&&
    current.archiveSha256===input.archiveSha256,'Completed customer receiving identity changed.');
  printResult(retained,true);
} else {
const result = retained??{schema:'commons.coingecko-complete-customer-receiving.v1',operation,input,
  sourceCommit:input.sourceCommit,sourcePins,node:process.version,
  startedAt:new Date().toISOString(),archive:{path:archive,bytes:originalBytes.length,sha256:digest(originalBytes),
    projectId:original.payload.project.id,revision:original.payload.project.revision},stages:[],attempts:[]};
const attempt={id:randomUUID(),startedAt:new Date().toISOString(),node:process.version,status:'RUNNING'};
result.attempts.push(attempt);result.status='RUNNING';
async function persist() {
  const next=resultPath+'.'+randomUUID()+'.next';
  try { await writeFile(next,JSON.stringify(result,null,2)+'\n',{flag:'wx',mode:0o600});await rename(next,resultPath); }
  finally { await unlink(next).catch(e=>{if(e.code!=='ENOENT')throw e;}); }
}
async function stage(name,fn) {
  const at=new Date().toISOString();
  try { const value=await fn();result.stages.push({name,attemptId:attempt.id,startedAt:at,completedAt:new Date().toISOString(),status:'PASS',value});await persist();return value; }
  catch(error){result.stages.push({name,attemptId:attempt.id,startedAt:at,completedAt:new Date().toISOString(),status:'FAILED',error:{code:error.code,message:error.message}});result.status='FAILED';attempt.status='FAILED';attempt.completedAt=new Date().toISOString();await persist();throw error;}
}
await stage('complete-customer-files',async()=>{
  const made=await product.createCoinGeckoDelivery({archive,output:deliveryDirectory});
  const checked=await product.inspectCoinGeckoDelivery({directory:deliveryDirectory});
  need(checked.manifest.archive.sha256===digest(originalBytes),'Original archive changed.');
  const repeated=await product.createCoinGeckoDelivery({archive,output:deliveryDirectory});
  need(repeated.replayed===true,'Completed customer files were not replayed.');
  return {directory:deliveryDirectory,manifestSha256:checked.manifestSha256,files:checked.deliveredFiles,bytes:checked.deliveredBytes,
    families:checked.manifest.families,sourceBases:checked.manifest.sourceBases,counts:checked.manifest.counts,replayed:repeated.replayed};
});
const received=await stage('independent-customer-project',async()=>{
  const value=await product.receiveCoinGeckoDelivery(receivingInput);
  need(value.status==='RECEIVED'&&value.recipientProjectId!==original.payload.project.id,'Expected an independently received project.');
  need(value.originalSourcesVerified===original.payload.files.length,'Expected every original source file.');
  return value;
});
await stage('same-original-operation',async()=>{
  const value=await product.receiveCoinGeckoDelivery(receivingInput);
  need(value.replayed===true&&value.recipientProjectId===received.recipientProjectId,'Receiving did not return the same original project.');
  return value;
});
const note=await stage('recipient-work',async()=>{
  const release=await serverModule.acquireWorkspaceLease(state);
  let model;
  try {
    model=new modelModule.MarketModel(state);
    const noteOperation=operation+'-recipient-note',prior=model.store.operation(received.recipientProjectId,noteOperation);
    if(prior.state==='RETAINED')return {noteId:prior.response.value.id,revision:model.project(received.recipientProjectId).project.revision,replayed:true};
    const request=model.store.list('requests',received.recipientProjectId,{limit:1}).items[0];
    need(request,'Original customer project has no retained request.');
    const current=model.project(received.recipientProjectId);
    const saved=model.saveNote(received.recipientProjectId,{opId:noteOperation,actor,revision:current.project.revision,note:{
      targetType:'request',targetId:request.id,title:'Customer handover received',
      text:'Received the complete retained market project. All '+received.originalSourcesVerified+' original source files have been verified; further review continues in this independently editable customer project.',
      type:'follow_up',status:'reviewed',assignee:'Commons'}});
    return {noteId:saved.value.id,revision:saved.revision,replayed:false};
  }finally{model?.close();await release();}
});
await stage('recipient-work-after-repeat-and-reopen',async()=>{
  const value=await product.receiveCoinGeckoDelivery(receivingInput);
  need(value.replayed===true&&value.recipientProjectId===received.recipientProjectId,'The repeated receiving changed the customer project.');
  need(value.currentProject.revision>=note.revision,'The repeated receiving lost recipient work.');
  const release=await serverModule.acquireWorkspaceLease(state);
  let model;
  try {
    model=new modelModule.MarketModel(state);
    const reopened=model.note(note.noteId).note;
    need(reopened.projectId===received.recipientProjectId,'The reopened customer note belongs to another project.');
    const current=model.project(received.recipientProjectId);
    return {recipientProjectId:current.project.id,revision:current.project.revision,noteId:reopened.id,counts:current.counts,replayed:value.replayed};
  }finally{model?.close();await release();}
});
result.status='RECEIVED';result.completedAt=new Date().toISOString();attempt.status='RECEIVED';attempt.completedAt=result.completedAt;
result.deliveryDirectory=deliveryDirectory;result.recipientStateDirectory=state;result.recipientProjectId=received.recipientProjectId;
await persist();
printResult(result,false);
}
